package com.vinaxmart.controller;
import com.vinaxmart.entity.*;import com.vinaxmart.repository.*;import org.springframework.security.core.Authentication;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/orders") public class OrderController{final OrderRepository orders;final CartItemRepository cart;final UserRepository users;OrderController(OrderRepository o,CartItemRepository c,UserRepository u){orders=o;cart=c;users=u;}@PostMapping @Transactional public Order checkout(Authentication a,@RequestBody Map<String,String> body){User u=users.findByEmail(a.getName()).orElseThrow();var ci=cart.findByUser(u);if(ci.isEmpty())throw new RuntimeException("Cart is empty");var items=new ArrayList<OrderItem>();double total=0;for(var x:ci){double price=x.getProduct().getPrice()*(1-x.getProduct().getDiscount()/100);items.add(OrderItem.builder().product(x.getProduct()).quantity(x.getQuantity()).price(price).selectedSize(x.getSelectedSize()).selectedVariant(x.getSelectedVariant()).build());total+=price*x.getQuantity();}Order o=Order.builder().user(u).items(items).total(total).status("CONFIRMED").paymentStatus("PENDING").address(body.getOrDefault("address","Not provided")).createdAt(LocalDateTime.now()).build();var saved=orders.save(o);cart.deleteByUser(u);return saved;}@GetMapping List<Order> mine(Authentication a){return orders.findByUserOrderByCreatedAtDesc(users.findByEmail(a.getName()).orElseThrow());}}